const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  let str = line
    .replaceAll(",", "")
    .replaceAll("111", "x")
    .replaceAll("11", "x")
    .replaceAll("1", "x");

  let count = 0;

  while (true) {
    let index = str.indexOf("x");
    if (index !== -1) {
      count++;
      str = str.slice(index + 1);
    } else {
      break;
    }
  }

  console.log(count);
});

