#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/*!
 * 字符串替换
 * @param s 主串
 * @param sub 目标子串
 * @param rep 替换子串
 * @return 一个新串，新串等价于主串将自身目标子串部分替换为rep串的结果
 */
char *replaceAll(char *s, char *sub, char *rep) {
    // 新串
    char *res = (char *) calloc(strlen(s), sizeof(char));

    // 目标子串长度
    int len = (int) strlen(sub);

    // 在主串中找到目标子串第一次出现的位置
    char *t = strstr(s, sub);
    while (t != NULL) {
        t[0] = '\0';
        strcat(res, s);
        strcat(res, rep);
        s = t + len;
        t = strstr(s, sub);
    }

    strcat(res, s);

    return res;
}

int main() {
    char s[1000] = {'\0'};
    int s_len = 0;

    char c;
    while (scanf("%c", &c)) {
        s[s_len++] = c;
        if (getchar() != ',') break;
    }

    // 先把卡车，即111的停车情况先弄出来(替换为x)，再将火车，即11的停车情况弄出来(替换为x)，最后再弄小车1的情况(替换为x)。

    char *res = replaceAll(replaceAll(replaceAll(s, "111", "x"), "11", "x"), "1", "x");

    int count = 0;

    // 统计x字符的数量，即为最少停车数量
    int i = 0;
    while (res[i] != '\0') {
        if (res[i] == 'x') {
            count++;
        }
        i++;
    }

    printf("%d\n", count);

    return 0;
}
